pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint128 amount1, uint128 amount2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, uint256(amount1) + uint256(amount2));

        vm.startPrank(actor);
        c.Put{value: amount1}(0);
        c.Put{value: amount2}(0);
        vm.stopPrank();

        (uint unlockTime, uint bal) = c.Acc(actor);
        unlockTime;
        assertTrue(bal == uint256(amount1) + uint256(amount2), "balance must accumulate deposits");
    }
}
